pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable to, uint256 vlen) public {
        // keep domain reasonable and wide: at least one recipient, and use the helper as callee
        vm.assume(to != address(0));
        // vlen will determine length; bound to small size to avoid OOG in test harness but still fuzzed
        uint256 len = bound(vlen, 1, 8);

        // build arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            // use the provided 'to' for all entries so the call target is an address with code
            tos[i] = to;
            vals[i] = uint(1); // minimal positive amount to satisfy any multiplications
        }

        // Deploy a helper contract at the 'to' address is not possible directly; instead deploy a callee
        // and ensure we pass its address to the contract C via its caddress public variable.
        // However, C has caddress hardcoded; we cannot change it. To ensure the low-level call succeeds,
        // we deploy a benign callee at any address (cannot control address), but low-level calls to EOAs succeed.
        // The distinguishing property here is about the returned boolean from transfer when it succeeds.

        // Make the caller the required msg.sender from reference contract
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.deal(requiredSender, 1 ether);
        vm.startPrank(requiredSender);
        bool ok;
        // call and capture whether it returns (does not revert) and capture the return value
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret; // this reads the returned boolean from transfer
        } catch {
            // if it reverts, we mark as not-ok by setting ok = false but this case does not help distinguish
            ok = false;
        }
        vm.stopPrank();

        // The universal property: whenever transfer completes, the reference returns true.
        // So assert that the observed return (ok) is true. This holds for the reference for all inputs
        // and will fail for the mutant for some inputs where transfer completes but returns false.
        assertTrue(ok);
    }
}

