// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an address to be used as one recipient and a uint256 value
    // The property: when called by the hardcoded owner and with a non-empty _tos array
    // and with a callee that accepts the low-level call, the reference should always return true.
    function testFuzz_property(address to, uint256 amount) public {
        // Keep domain wide but ensure recipient is not zero address to avoid trivial edge cases
        vm.assume(to != address(0));
        // Ensure amount maps to a usable index and non-zero sized arrays
        // We'll construct single-element arrays for simplicity
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = amount;

        // The contract C expects msg.sender to be a specific hardcoded owner address.
        // We must prank as that address so the call is admissible.
        address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(owner);

        // Call transfer and capture whether it completed (no revert) and the returned boolean.
        bool ok;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // For the reference contract, when the call does not revert, it must return true.
        // We assert that either the call reverted (ok == false) OR the returned value is true.
        // This is equivalent to: if the call completed, its return value is true.
        assertTrue(!ok || ret);
    }
}
